using System;using System.IO;using Mono.Cecil;
class VerifyManagerSnapshots {static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(args.Length>2?args[2]:Path.GetDirectoryName(args[0]));using(var before=AssemblyDefinition.ReadAssembly(args[0],new ReaderParameters{AssemblyResolver=resolver}))using(var after=AssemblyDefinition.ReadAssembly(args[1])){int sites=ManagerSnapshotPatch.Reverse(before,after),methods,instructions;AssemblyStructure.RequireSame(before,after,out methods,out instructions);Console.WriteLine("Verified "+sites+" snapshot leases and exact reversal of "+methods+" methods / "+instructions+" instructions.");}}}
